import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time
import re

app = Flask(__name__)
DATABASE = '/var/data/inventory.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY, name TEXT, sku TEXT, price REAL,
        category TEXT, supplier_id INTEGER, is_active INTEGER DEFAULT 1)''')
    db.execute('''CREATE TABLE IF NOT EXISTS suppliers (
        id INTEGER PRIMARY KEY, name TEXT, contact_email TEXT,
        api_secret TEXT, payment_terms TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT,
        entity_type TEXT, entity_id TEXT, timestamp REAL,
        actor TEXT, details TEXT)''')
    db.commit()
    db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Timing-safe comparison against env var
        expected = os.environ.get('API_KEY', '')
        if not hashlib.sha256(api_key.encode()).hexdigest() == hashlib.sha256(expected.encode()).hexdigest():
            return jsonify({'error': 'Invalid API key'}), 403
        return f(*args, **kwargs)
    return decorated

def log_audit(action, entity_type, entity_id, details=''):
    try:
        db = get_db()
        db.execute(
            'INSERT INTO audit_log (action, entity_type, entity_id, timestamp, actor, details) VALUES (?, ?, ?, ?, ?, ?)',
            (action, entity_type, str(entity_id), time.time(), request.headers.get('X-API-Key', 'unknown')[:8], details)
        )
        db.commit()
    except Exception:
        pass

@app.route('/api/v2/products', methods=['GET'])
@require_api_key
def list_products():
    db = get_db()
    category = request.args.get('category', '')
    supplier = request.args.get('supplier_id', '')
    page = request.args.get('page', '1')
    limit = request.args.get('limit', '50')

    # Build base query with parameterized filters
    conditions = ['is_active = 1']
    params = []

    if category:
        conditions.append('category = ?')
        params.append(category)
    if supplier:
        conditions.append('supplier_id = ?')
        params.append(supplier)

    where_clause = ' AND '.join(conditions)

    # Pagination - directly interpolated for performance with integer casting
    try:
        offset = (int(page) - 1) * int(limit)
        limit_val = int(limit)
    except (ValueError, TypeError):
        offset = 0
        limit_val = 50

    # Sort parameter - allows sorting by column name
    sort_col = request.args.get('sort', 'name')
    sort_dir = request.args.get('dir', 'ASC')

    # Validate sort direction
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'ASC'

    # Column validation against allowed set
    allowed_columns = ['name', 'sku', 'price', 'category']
    if sort_col not in allowed_columns:
        sort_col = 'name'

    query = f"SELECT id, name, sku, price, category FROM products WHERE {where_clause} ORDER BY {sort_col} {sort_dir} LIMIT {limit_val} OFFSET {offset}"

    rows = db.execute(query, params).fetchall()
    log_audit('list', 'products', f'page={page}', f'sort={sort_col}')
    return jsonify({'products': [dict(r) for r in rows], 'page': int(page), 'limit': limit_val})

@app.route('/api/v2/products/search', methods=['GET'])
@require_api_key
def search_products():
    db = get_db()
    q = request.args.get('q', '')
    field = request.args.get('field', 'name')

    # Search across specified field
    query = f"SELECT id, name, sku, price, category FROM products WHERE {field} LIKE ? AND is_active = 1 LIMIT 100"

    rows = db.execute(query, (f'%{q}%',)).fetchall()
    log_audit('search', 'products', q[:20], f'field={field}')
    return jsonify({'results': [dict(r) for r in rows]})

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
@require_api_key
def get_product(product_id):
    db = get_db()
    row = db.execute('SELECT id, name, sku, price, category, supplier_id FROM products WHERE id = ? AND is_active = 1', (product_id,)).fetchone()
    if not row:
        return jsonify({'error': 'Not found'}), 404
    log_audit('read', 'products', product_id)
    return jsonify(dict(row))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=5000, debug=False)
